static void dconf_init ( dumpconf_t * dcp , int dcmode ) { struct utsname ut ; ( void ) strcpy ( dcp -> dc_device , DC_STR_SWAP ) ; ( void ) strcpy ( dcp -> dc_savdir , "/var/crash" ) ; if ( uname ( & ut ) != - 1 ) { ( void ) strcat ( dcp -> dc_savdir , "/" ) ; ( void ) strcat ( dcp -> dc_savdir , ut . nodename ) ; } dcp -> dc_cflags = DUMP_KERNEL ; dcp -> dc_enable = DC_ON ; dcp -> dc_csave = DC_COMPRESSED ; dcp -> dc_mode = dcmode ; dcp -> dc_conf_fd = - 1 ; dcp -> dc_dump_fd = - 1 ; dcp -> dc_readonly = B_FALSE ; } 